import SwiftUI

/// Local projection, explicitly separate from an answer generated by a provider.
struct AssistantWikiReadingView: View {
    let snapshot: PatientWikiReadingSnapshot
    @Binding var source: PatientHistoryEntry?

    private var sourceEntries: [String: PatientHistoryEntry] {
        Dictionary(uniqueKeysWithValues: snapshot.entries.enumerated().map { ("F\($0.offset + 1)", $0.element) })
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text(snapshot.patient.displayName).font(.headline)
            if source != nil {
                Button("Voltar à wiki e IPS", systemImage: "chevron.left") { source = nil }
            }
            ScrollView {
                VStack(alignment: .leading, spacing: 12) {
                    if let source {
                        Text(source.title).font(.headline)
                        Text(source.displayDate + " · " + source.status).font(.caption).foregroundStyle(.secondary)
                        ClinicalFormattedText(text: source.text).textSelection(.enabled)
                    } else {
                        Text("Consulta local · fontes conferidas ao abrir").font(.caption).foregroundStyle(.secondary)
                        Text(freshnessText).font(.callout)
                        ForEach(Array(snapshot.wikiParagraphs.enumerated()), id: \.offset) { _, paragraph in
                            if !paragraph.title.isEmpty { Text(paragraph.title).font(.headline) }
                            PatientWikiInlineText(text: paragraph.text, sourceEntries: sourceEntries) { source = $0 }
                        }
                        Divider()
                        Text("Dados revisados para IPS").font(.headline)
                        if let issue = snapshot.reviewsIssue { Text(issue).font(.callout) }
                        if !snapshot.outdatedAcceptedIDs.isEmpty {
                            Text("\(snapshot.outdatedAcceptedIDs.count) revisões aguardam fontes atuais e ficaram fora desta leitura.")
                                .font(.callout)
                        }
                        if snapshot.acceptedIPS.isEmpty {
                            Text("Nenhum dado revisado elegível neste recorte.").foregroundStyle(.secondary)
                        }
                        ForEach(snapshot.acceptedIPS, id: \.fact.id) { item in
                            if snapshot.conflictingAcceptedIDs.contains(item.fact.id) {
                                Label("Dados divergentes: conferir fontes", systemImage: "exclamationmark.triangle")
                            }
                            PatientWikiInlineText(text: PatientWikiExport.factDescription(item.fact, note: item.note) + " [F\(item.sourceNumber)]",
                                sourceEntries: sourceEntries) { source = $0 }
                        }
                        Text("Ausência na wiki ou no IPS não significa ausência no prontuário. A síntese é derivada de IA; revisão e atualidade das fontes não confirmam a situação clínica atual.")
                            .font(.caption).foregroundStyle(.secondary)
                        Text(snapshot.exclusions.description).font(.caption).foregroundStyle(.secondary)
                    }
                }.frame(maxWidth: .infinity, alignment: .leading).padding(.trailing, 8)
            }.frame(height: 300)
        }
    }

    private var freshnessText: String {
        switch snapshot.freshness {
        case .current: "Wiki atual quanto às fontes."
        case .outdated: "Wiki desatualizada. Atualize o resumo na página do paciente; o texto antigo ficou fora desta leitura."
        case .missing: "Este paciente ainda não tem wiki gerada."
        case .invalid: "A wiki não pôde ser verificada. O conteúdo não foi apresentado."
        }
    }
}
